using Path=System.IO.Path;using System;using System.Collections.Generic;using System.IO;using System.Linq;using System.Net.Http;using System.Runtime.Serialization;using System.Speech.Recognition;using System.Speech.Synthesis;using System.Text;using System.Threading;using System.Threading.Tasks;using System.Windows;using System.Windows.Controls;using System.Windows.Input;using System.Windows.Media;using System.Windows.Shapes;using System.Windows.Threading;
namespace SeraphimLuxury {
 [DataContract] class ChatTurn {[DataMember]public string role;[DataMember]public string content;}
 [DataContract] class ChatRequest {[DataMember]public string model;[DataMember]public List<ChatTurn> messages;[DataMember]public bool stream;}
 [DataContract] class ChatResponse {[DataMember]public ChatTurn message;[DataMember]public string error;}
 [DataContract] class LocalModel {[DataMember]public string name;}
 [DataContract] class ModelList {[DataMember]public List<LocalModel> models;}
 static class LocalAssistant {
  internal static string Endpoint="http://127.0.0.1:11434";
  internal static async Task<List<string>> Models(){using(var client=new HttpClient {Timeout=TimeSpan.FromSeconds(4)}){var data=Json.Read<ModelList>(await client.GetStringAsync(Endpoint+"/api/tags"));return (data.models??new List<LocalModel>()).Select(m=>m.name).Where(n=>n!=null).ToList();}}
  internal static async Task<string> Ask(string model,List<ChatTurn> messages,CancellationToken cancel){if(!System.Text.RegularExpressions.Regex.IsMatch(model??"","^[A-Za-z0-9._:/-]{1,100}$"))throw new IOException("Choisissez le nom du modèle local.");using(var client=new HttpClient {Timeout=TimeSpan.FromMinutes(3)})using(var body=new StringContent(Json.Write(new ChatRequest {model=model,messages=messages.TakeLastCompat(24).ToList(),stream=false}),Encoding.UTF8,"application/json")){using(var response=await client.PostAsync(Endpoint+"/api/chat",body,cancel)){string json=await response.Content.ReadAsStringAsync();if(!response.IsSuccessStatusCode)throw new IOException("Le modèle local n’est pas disponible. Vérifiez Ollama et son nom de modèle.");if(json.Length>1000000)throw new IOException("Réponse trop volumineuse.");var reply=Json.Read<ChatResponse>(json);if(reply.message==null||String.IsNullOrWhiteSpace(reply.message.content))throw new IOException("Le service n’a pas renvoyé de réponse.");return reply.message.content;}}}
 }
 static class EnumerableTail {public static IEnumerable<T> TakeLastCompat<T>(this IEnumerable<T> source,int n){var array=source.ToArray();return array.Skip(Math.Max(0,array.Length-n));}}
 class AssistantSigil:Grid {
  readonly DispatcherTimer timer;double phase;readonly FrameworkElement eye;readonly StackPanel dots;public bool Active;
  public AssistantSigil(){Width=100;Height=100;IsHitTestVisible=false;eye=Branding.Eye(76,true,true);Children.Add(eye);dots=new StackPanel {Orientation=Orientation.Horizontal,HorizontalAlignment=HorizontalAlignment.Center,VerticalAlignment=VerticalAlignment.Center};for(int i=0;i<3;i++)dots.Children.Add(new Ellipse {Width=6,Height=6,Fill=Visuals.Gold,Margin=new Thickness(4)});Children.Add(dots);timer=new DispatcherTimer {Interval=TimeSpan.FromMilliseconds(40)};timer.Tick+=delegate {phase+=.04;eye.Opacity=Active?.25+.6*(.5+.5*Math.Sin(phase*2)):.9;dots.Opacity=Active?1-eye.Opacity:0;for(int i=0;i<3;i++)((Ellipse)dots.Children[i]).RenderTransform=new TranslateTransform(0,Active?Math.Sin(phase*5+i)*4:0);InvalidateVisual();};Loaded+=delegate{timer.Start();};Unloaded+=delegate{timer.Stop();};}
  protected override void OnRender(DrawingContext d){base.OnRender(d);double r=Math.Min(ActualWidth,ActualHeight)*.46;var pen=new Pen(AtlasPalette.Brush("#B5A0DD",Active?.6:.25),.6);d.DrawEllipse(null,pen,new Point(ActualWidth/2,ActualHeight/2),r,r);if(Active)d.DrawEllipse(null,new Pen(AtlasPalette.Brush("#BAA5F0",.12),.5),new Point(ActualWidth/2,ActualHeight/2),r+3*Math.Sin(phase*3),r+3*Math.Sin(phase*3));}
 }
 class AssistantWindow:Window {
  readonly Preferences prefs;readonly Func<bool> save;readonly string chatPath;readonly StackPanel transcript=new StackPanel();readonly ScrollViewer scroll;readonly TextBox input,model;readonly TextBlock status;readonly AssistantSigil sigil;readonly Button send;readonly CheckBox spoken;List<ChatTurn> turns=new List<ChatTurn>();CancellationTokenSource cancel;SpeechRecognitionEngine recognition;SpeechSynthesizer speech;bool busy,closed;
  public AssistantWindow(Preferences p,string root,Func<bool> persist){prefs=p;save=persist;chatPath=Path.Combine(root,"assistant-chat.json");Title="Seraphim · Assistant";Width=420;Height=680;MinWidth=340;MinHeight=420;WindowStyle=WindowStyle.None;AllowsTransparency=true;Background=Brushes.Transparent;ResizeMode=ResizeMode.CanResizeWithGrip;ShowInTaskbar=false;Left=Math.Max(0,SystemParameters.WorkArea.Right-Width-25);Top=Math.Max(0,SystemParameters.WorkArea.Bottom-Height-25);var grid=new Grid {Margin=new Thickness(20)};for(int i=0;i<6;i++)grid.RowDefinitions.Add(new RowDefinition {Height=i==3?new GridLength(1,GridUnitType.Star):GridLength.Auto});var head=new Grid();head.MouseLeftButtonDown+=delegate(object s,MouseButtonEventArgs e){if(e.ButtonState==MouseButtonState.Pressed)DragMove();};head.Children.Add(Visuals.TextBlock("SERAPHIM / IA",11,Visuals.Gold));var tools=new StackPanel {Orientation=Orientation.Horizontal,HorizontalAlignment=HorizontalAlignment.Right};var pin=Visuals.Button("◎",delegate {Topmost=!Topmost;});pin.ToolTip="Toujours devant";var small=Visuals.Button("◫",delegate {Height=Height>460?440:680;});small.ToolTip="Format compact";var hide=Visuals.Button("×",Close);foreach(var b in new[]{pin,small,hide}){b.Width=32;b.MinHeight=25;b.Padding=new Thickness(0);b.Background=Brushes.Transparent;tools.Children.Add(b);}head.Children.Add(tools);grid.Children.Add(head);
   var presence=new StackPanel {HorizontalAlignment=HorizontalAlignment.Center};sigil=new AssistantSigil();presence.Children.Add(sigil);status=Visuals.TextBlock("Ollama local · vérifier le service avant de parler",10,Visuals.Muted);status.MaxWidth=340;status.TextAlignment=TextAlignment.Center;presence.Children.Add(status);Grid.SetRow(presence,1);grid.Children.Add(presence);
   var settings=new Grid {Margin=new Thickness(0,14,0,14)};settings.ColumnDefinitions.Add(new ColumnDefinition());settings.ColumnDefinitions.Add(new ColumnDefinition {Width=GridLength.Auto});model=new TextBox {Text=p.AiModel??"",ToolTip="Nom du modèle local Ollama",MaxLength=100,Padding=new Thickness(9),FontSize=11};System.Windows.Automation.AutomationProperties.SetName(model,"Modèle Ollama");settings.Children.Add(model);var detect=Visuals.Button("Détecter",delegate {Detect();});detect.FontSize=10;detect.Padding=new Thickness(10,5,10,5);Grid.SetColumn(detect,1);settings.Children.Add(detect);Grid.SetRow(settings,2);grid.Children.Add(settings);
   scroll=new ScrollViewer {Content=transcript,VerticalScrollBarVisibility=ScrollBarVisibility.Auto,HorizontalScrollBarVisibility=ScrollBarVisibility.Disabled};Grid.SetRow(scroll,3);grid.Children.Add(scroll);try{if(File.Exists(chatPath))turns=Json.Read<List<ChatTurn>>(File.ReadAllText(chatPath)).Where(t=>t!=null&&(t.role=="user"||t.role=="assistant")&&t.content!=null).TakeLastCompat(100).ToList();}catch{}foreach(var t in turns)Bubble(t);
   input=new TextBox {AcceptsReturn=true,TextWrapping=TextWrapping.Wrap,MinHeight=70,MaxHeight=140,MaxLength=8000,VerticalScrollBarVisibility=ScrollBarVisibility.Auto,Padding=new Thickness(12),Margin=new Thickness(0,14,0,10)};System.Windows.Automation.AutomationProperties.SetName(input,"Votre message à l’assistant");input.PreviewKeyDown+=delegate(object s,KeyEventArgs e){if(e.Key==Key.Enter&&(Keyboard.Modifiers&ModifierKeys.Shift)==0){e.Handled=true;Send();}};Grid.SetRow(input,4);grid.Children.Add(input);var actions=new WrapPanel();send=Visuals.Button("Envoyer ↗",Send);var stop=Visuals.Button("Arrêter",delegate {if(cancel!=null)cancel.Cancel();StopListening();if(speech!=null)speech.SpeakAsyncCancelAll();});var voice=Visuals.Button("◉",Listen);voice.ToolTip="Microphone · reconnaissance vocale Windows locale, si disponible";voice.Content=new Border {Width=34,Height=34,CornerRadius=new CornerRadius(17),BorderThickness=new Thickness(.7),BorderBrush=Visuals.Gold,Child=new Viewbox {Width=23,Height=23,Child=new System.Windows.Shapes.Path {Data=Geometry.Parse("M5,12 V16 M10,7 V21 M15,4 V24 M20,7 V21 M25,12 V16"),Stroke=Visuals.Gold,StrokeThickness=2.5,StrokeStartLineCap=PenLineCap.Round,StrokeEndLineCap=PenLineCap.Round}}};voice.Width=36;voice.Height=36;voice.Padding=new Thickness(0);var clear=Visuals.Button("Effacer",delegate {if(busy)return;turns.Clear();transcript.Children.Clear();Persist();});spoken=new CheckBox {Content="Lire",IsChecked=false,VerticalAlignment=VerticalAlignment.Center,ToolTip="Lire les réponses avec une voix Windows"};foreach(var b in new[]{send,stop,voice,clear}){b.FontSize=10;b.Margin=new Thickness(0,0,5,0);actions.Children.Add(b);}actions.Children.Add(spoken);Grid.SetRow(actions,5);grid.Children.Add(actions);Content=new Border {Child=grid,CornerRadius=new CornerRadius(20),BorderBrush=AtlasPalette.Brush("#B49CD2",.35),BorderThickness=new Thickness(.7),Background=new LinearGradientBrush(Visuals.Color("#F31A1723"),Visuals.Color("#F310111A"),90)};Closed+=delegate {closed=true;if(cancel!=null)cancel.Cancel();StopListening();if(speech!=null){speech.SpeakAsyncCancelAll();speech.Dispose();}Persist();};}
  async void Detect(){status.Text="Recherche du service local…";try{var models=await LocalAssistant.Models();if(closed)return;if(models.Count==0){status.Text="Ollama répond, mais aucun modèle n’est installé.";return;}model.Text=models.Contains(model.Text)?model.Text:models[0];prefs.AiModel=model.Text;save();status.Text="Ollama connecté · "+models.Count+" modèle(s) local(aux)";}catch{if(!closed)status.Text="Service local absent. Installez Ollama et un modèle, ou raccordez votre future API.";}}
  void Bubble(ChatTurn turn){var text=Visuals.TextBlock(turn.content,13,Visuals.Text);text.Margin=new Thickness(0,7,0,15);var body=new StackPanel();body.Children.Add(Visuals.TextBlock(turn.role=="user"?"VOUS":"SERAPHIM · OLLAMA LOCAL",8,Visuals.Muted));body.Children.Add(text);transcript.Children.Add(new Border {Child=body,Padding=new Thickness(10,14,10,2),BorderThickness=new Thickness(0,0,0,.5),BorderBrush=Visuals.Line});scroll.ScrollToEnd();}
  void Persist(){try{Directory.CreateDirectory(Path.GetDirectoryName(chatPath));File.WriteAllText(chatPath,Json.Write(turns.TakeLastCompat(100).ToList()),Encoding.UTF8);}catch{}}
  async void Send(){if(busy||String.IsNullOrWhiteSpace(input.Text))return;string text=input.Text.Trim();if(String.IsNullOrWhiteSpace(model.Text)){status.Text="Détectez ou renseignez le modèle local avant d’envoyer.";return;}StopListening();busy=true;send.IsEnabled=false;sigil.Active=true;cancel=new CancellationTokenSource();var turn=new ChatTurn {role="user",content=text};turns.Add(turn);Bubble(turn);input.Clear();status.Text="Le modèle local prépare sa réponse…";try{prefs.AiModel=model.Text;save();string reply=await LocalAssistant.Ask(model.Text,turns,cancel.Token);if(closed)return;var answer=new ChatTurn {role="assistant",content=reply};turns.Add(answer);Bubble(answer);status.Text="Réponse du modèle local · vérifiez les informations importantes.";if(spoken.IsChecked==true){try{if(speech==null){speech=new SpeechSynthesizer();speech.SpeakStarted+=delegate {Dispatcher.BeginInvoke(new Action(delegate {if(!closed)sigil.Active=true;}));};speech.SpeakCompleted+=delegate {Dispatcher.BeginInvoke(new Action(delegate {if(!closed)sigil.Active=false;}));};}speech.SpeakAsync(reply.Substring(0,Math.Min(10000,reply.Length)));}catch{status.Text="Réponse disponible en texte ; voix Windows indisponible.";}}}catch(OperationCanceledException){if(!closed)status.Text="Réponse interrompue.";}catch{if(!closed)status.Text="Le service local ne répond pas. Aucune réponse IA n’a été inventée.";}finally{busy=false;if(!closed){send.IsEnabled=true;sigil.Active=false;}Persist();cancel.Dispose();cancel=null;}}
  void Listen(){if(recognition!=null){StopListening();status.Text="Microphone arrêté.";sigil.Active=false;return;}try{var recognizer=SpeechRecognitionEngine.InstalledRecognizers().FirstOrDefault(r=>r.Culture.TwoLetterISOLanguageName=="fr");if(recognizer==null){status.Text="Reconnaissance vocale française Windows absente · API de transcription à raccorder.";return;}recognition=new SpeechRecognitionEngine(recognizer);recognition.LoadGrammar(new DictationGrammar());recognition.SpeechRecognized+=delegate(object sender,SpeechRecognizedEventArgs e){Dispatcher.BeginInvoke(new Action(delegate {if(!closed){input.Text=(input.Text+" "+e.Result.Text).Trim();status.Text="Texte reconnu localement · Envoyer pour confirmer.";}}));};recognition.SetInputToDefaultAudioDevice();recognition.RecognizeAsync(RecognizeMode.Multiple);status.Text="Microphone actif · reconnaissance locale · Arrêter pour couper";sigil.Active=true;}catch{StopListening();status.Text="Microphone indisponible. Vérifiez son accès dans Windows.";}}
  void StopListening(){if(recognition==null)return;try{recognition.RecognizeAsyncCancel();recognition.Dispose();}catch{}recognition=null;sigil.Active=false;}
 }
}
